#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_coverage;
uniform float amzp_softness;
uniform float amzp_turb;
uniform float amzp_drift;
uniform float amzp_driftAngle;
uniform float amzp_evolve;
layout(color) uniform half4 amzp_cloudCol;
layout(color) uniform half4 amzp_darkCol;
uniform float amzp_showSky;
layout(color) uniform half4 amzp_skyCol;
uniform float amzp_flashRate;
uniform float amzp_flashLen;
uniform float amzp_flashInt;
uniform float amzp_flashSize;
uniform float amzp_flashArea;
uniform float amzp_crackle;
uniform float amzp_crackleScale;
layout(color) uniform half4 amzp_flashCol;
uniform float amzp_bolts;
uniform float amzp_boltW;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_detail;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 78.233) * 43758.5453123); }
    float h21(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 17.13) * 43758.5453123); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(h21(i), h21(i + float2(1.0, 0.0)), f.x), mix(h21(i + float2(0.0, 1.0)), h21(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p, float ev) {
        float n = floor(clamp(amzp_detail, 1.0, 10.0) + 0.5);
        float s = 0.0, a = 0.5, ws = 0.0;
        for (int i = 0; i < 10; i++) {
            if (float(i) >= n) break;
            s += a * vn(p + float2(ev * (1.0 + float(i) * 0.3), -ev * 0.7));
            ws += a;
            p = advRot(p, 0.55) * 2.03 + float2(1.7, 9.2);
            a *= 0.5;
        }
        return s / max(ws, 1e-5);
    }
    float ridge(float2 p) {
        float s = 0.0, a = 0.5;
        for (int i = 0; i < 4; i++) {
            float v = 1.0 - abs(vn(p) * 2.0 - 1.0);
            s += a * v * v;
            p = advRot(p, 0.9) * 2.1 + float2(3.3, 1.1);
            a *= 0.55;
        }
        return s;
    }
    float3 HS;
    float cloudAt(float2 p, float ev) {
        float2 w = float2(fbm(p * 0.8 + float2(0.0, ev * 0.5), ev), fbm(p * 0.8 + float2(5.2, 1.3 - ev * 0.5), ev));
        float d = fbm(p + (w - 0.5) * 2.0 * amzp_turb, ev);
        float th = 1.0 - amzp_coverage;
        float sf = amzp_softness * 0.35;
        return smoothstep(th - sf, th + sf, d);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float ps = pxs();
        float t = TT();
        float unit = 420.0 * ps * max(amzp_scale * 2.0, 0.002);
        float2 ctrPx = 0.5 * W + float2(amzp_position.x, -amzp_position.y) * ps;
        float2 dd = advRot(float2(1.0, 0.0), radians(amzp_driftAngle));
        float2 pp = advRot(uv * W - ctrPx, radians(amzp_angle)) / max(amzp_stretch, float2(0.01));
        float2 p = (pp - dd * amzp_drift * ps * t) / unit;
        float ev = t * amzp_evolve;
        float c = cloudAt(p, ev);
        float c2 = cloudAt(p + float2(0.0, 0.06), ev);
        float shade = clamp(1.0 - (c2 - c) * 2.5, 0.25, 1.2);
        float thin = c * (1.0 - c) * 4.0;
        float3 col = mix(amzp_darkCol.rgb, amzp_cloudCol.rgb, clamp(c * 0.65 * shade + thin * 0.25, 0.0, 1.0));
        float3 light = float3(0.0);
        float rate = max(amzp_flashRate, 0.0);
        float lmin = min(W.x, W.y);
        for (int ch = 0; ch < 2; ch++) {
            if (rate <= 0.0) break;
            float fc = float(ch);
            float tt = t * rate + fc * 0.5 + h1(fc * 3.1) ;
            float k = floor(tt);
            float id = k * 2.0 + fc;
            float st = h1(id * 1.7) * 0.6;
            float tau = (fract(tt) - st) / max(amzp_flashLen * rate, 0.001);
            if (tau < 0.0 || tau > 1.0) continue;
            if (h1(id * 5.3 + 2.0) > 0.85) continue;
            float pulses = 2.0 + floor(h1(id * 9.1) * 3.0);
            float env = exp(-tau * 3.5) * (0.55 + 0.45 * step(0.45, fract(tau * pulses))) * smoothstep(0.0, 0.03, tau);
            float2 fpos = 0.5 * W + (float2(h1(id * 2.3), h1(id * 4.7)) - 0.5) * W * amzp_flashArea * float2(1.0, 0.8);
            fpos.y += W.y * 0.08;
            float r = amzp_flashSize * lmin * (0.7 + 0.6 * h1(id * 6.1));
            float2 dp = uv * W - fpos;
            float g = exp(-dot(dp, dp) / max(r * r, 1.0));
            light += amzp_flashCol.rgb * env * g * (0.25 + c * 0.9 + thin * 0.8) * amzp_flashInt;
            if (amzp_crackle > 0.0) {
                float2 vp = p * 3.0 / max(amzp_crackleScale, 0.05) + float2(id * 13.7, id * 7.1);
                float2 bw2 = vp + (float2(vn(vp * 2.0), vn(vp * 2.0 + 5.0)) - 0.5) * 0.9;
                float r1 = 1.0 - abs(vn(bw2) * 2.0 - 1.0);
                float r2 = 1.0 - abs(vn(bw2 * 2.7 + 3.0) * 2.0 - 1.0);
                float r3 = 1.0 - abs(vn(bw2 * 6.1 + 7.0) * 2.0 - 1.0);
                float vein = smoothstep(0.86, 0.985, r1) + smoothstep(0.88, 0.99, r2) * 0.7 + smoothstep(0.9, 0.99, r3) * 0.45 * r1;
                vein *= 0.55 + 0.9 * h21(floor(uv * W / max(ps, 0.5)) + id);
                light += amzp_flashCol.rgb * vein * env * smoothstep(0.02, 0.45, g) * smoothstep(0.08, 0.45, c) * amzp_crackle * amzp_flashInt * 1.6;
            }
            if (amzp_bolts > 0.0 && h1(id * 8.9 + 1.0) < amzp_bolts) {
                float2 q = uv * W;
                float below = fpos.y - q.y;
                float L = W.y * (0.35 + 0.5 * h1(id * 3.9));
                if (below > 0.0 && below < L) {
                    float yy = below / L;
                    float xo = fpos.x + (fbm(float2(yy * 6.0, id * 3.3), 0.0) - 0.5) * lmin * 0.5 * yy;
                    float bw = amzp_boltW * ps;
                    float d = abs(q.x - xo);
                    float tip = (1.0 - smoothstep(0.85, 1.0, yy)) * smoothstep(0.0, 0.18, yy);
                    float b = (1.0 - smoothstep(bw * 0.5, bw * 0.5 + 1.0, d)) * 1.5 + exp(-d / (bw * 4.0 + 2.0)) * 0.6;
                    float xb = xo + (yy - 0.3) * lmin * 0.25 * (h1(id * 2.9) - 0.5) * 2.0 + (fbm(float2(yy * 9.0, id * 5.1), 0.0) - 0.5) * lmin * 0.15;
                    float db = abs(q.x - xb);
                    float br = ((1.0 - smoothstep(bw * 0.3, bw * 0.3 + 1.0, db)) + exp(-db / (bw * 3.0 + 2.0)) * 0.4) * smoothstep(0.3, 0.38, yy) * (1.0 - smoothstep(0.55, 0.7, yy));
                    light += amzp_flashCol.rgb * (b + br) * tip * env * amzp_flashInt;
                }
            }
        }
        col += light;
        float ca = clamp(c + max(light.r, max(light.g, light.b)) * 0.5, 0.0, 1.0);
        float4 G;
        if ((amzp_showSky>0.5)) G = float4(mix(amzp_skyCol.rgb, col, c) + light * (1.0 - c), 1.0);
        else G = float4(col * ca, ca);
        G.rgb = min(G.rgb, float3(G.a));
        amzOutput = nmBlend(orig, nmGradMap(G));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
